Add-Rule @{ Name = 'FWShift-Block_RDP_from_the_guest_half_of_the_admin_network'; DisplayName = 'Block RDP from the guest half of the admin network'; Description = 'FWShift: Block RDP from the guest half of the admin network'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('3389'); RemoteAddress = @('192.0.2.128/25') }
