Add-Rule @{ Name = 'FWShift-Web_out_on_private_networks'; DisplayName = 'Web out on private networks'; Description = 'FWShift: Web out on private networks'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'True'; Profile = 'Private'; Protocol = 'TCP'; RemotePort = @('80', '443') }
